// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number) internal {
        vm.assume(_number > 0);
        uint64 numberBefore;
        try c.number() returns (uint64 __r) { numberBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(
            _number,
            0,
            0,
            bytes32(0),
            0,
            bytes32(0),
            0,
            0
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.number() == numberBefore);
    }

    function testFuzz_run(uint64 _number) public {
        _run(_number);
    }

    receive() external payable {}
}
